package main

import (
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type DiscRec struct { // 01 DISC-REC, 15 bytes
	DrItem  string          // PIC X(6) @0 len=6
	DrPrice decimal.Decimal // PIC 9(5)V99 @6 len=7
	DrPct   int64           // PIC 9(2) @13 len=2
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N"                            // PIC X len=1 = "N"
var WsDiscount decimal.Decimal = decimal.NewFromInt(0) // PIC 9(5)V99 len=7 = 0
var WsNet decimal.Decimal = decimal.NewFromInt(0)      // PIC 9(5)V99 len=7 = 0
var WsTotalNet decimal.Decimal = decimal.NewFromInt(0) // PIC 9(8)V99 len=10 = 0
var WsCount int64 = 0                                   // PIC 9(3) len=3 = 0
var WsPriceEd string                                    // PIC ZZ,ZZ9.99 len=9
var WsDiscEd string                                     // PIC ZZ,ZZ9.99 len=9
var WsNetEd string                                      // PIC ZZ,ZZ9.99 len=9
var WsTotalEd string                                    // PIC ZZ,ZZZ,ZZ9.99 len=13

var discRec DiscRec
var discLines []string
var discIdx int

func pow10Int64(n int) int64 {
	var p int64 = 1
	for i := 0; i < n; i++ {
		p *= 10
	}
	return p
}

func storeDecimal(v decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	scaled := v.Shift(scale).Truncate(0)
	totalDigits := intDigits + int(scale)
	modulus := pow10Int64(totalDigits)
	if modulus == 0 {
		return v
	}
	scaledInt := scaled.IntPart()
	rem := scaledInt % modulus
	return decimal.New(rem, -scale)
}

func formatEdited(val decimal.Decimal, pic string) string {
	absVal := val
	if val.IsNegative() {
		absVal = val.Abs()
	}
	dotIdx := strings.Index(pic, ".")
	var intPic, fracPic string
	if dotIdx >= 0 {
		intPic = pic[:dotIdx]
		fracPic = pic[dotIdx+1:]
	} else {
		intPic = pic
		fracPic = ""
	}
	intCap := 0
	for _, ch := range intPic {
		if ch == 'Z' || ch == '9' || ch == '0' {
			intCap++
		}
	}
	fracLen := 0
	for _, ch := range fracPic {
		if ch == 'Z' || ch == '9' || ch == '0' {
			fracLen++
		}
	}
	totalCap := intCap + fracLen
	scaled := absVal.Shift(int32(fracLen)).Truncate(0)
	scaledInt := scaled.IntPart()
	mod := pow10Int64(totalCap)
	scaledMod := scaledInt % mod
	if scaledMod < 0 {
		scaledMod = -scaledMod
	}
	powFrac := pow10Int64(fracLen)
	var intPart, fracPart int64
	if fracLen > 0 {
		intPart = scaledMod / powFrac
		fracPart = scaledMod % powFrac
	} else {
		intPart = scaledMod
		fracPart = 0
	}
	intDigitsStr := fmt.Sprintf("%0*d", intCap, intPart)

	digitIndices := []int{}
	for i, ch := range intPic {
		if ch == 'Z' || ch == '9' {
			digitIndices = append(digitIndices, i)
		}
	}
	outInt := []byte(intPic)
	suppress := true
	for idx, picIdx := range digitIndices {
		placeholder := intPic[picIdx]
		var digitChar byte
		if idx < len(intDigitsStr) {
			digitChar = intDigitsStr[idx]
		} else {
			digitChar = '0'
		}
		if placeholder == '9' {
			suppress = false
			outInt[picIdx] = digitChar
		} else { // Z
			if suppress && digitChar == '0' {
				outInt[picIdx] = ' '
			} else {
				suppress = false
				outInt[picIdx] = digitChar
			}
		}
	}
	for i, ch := range intPic {
		if ch == ',' {
			hasPrinted := false
			for _, dIdx := range digitIndices {
				if dIdx < i && outInt[dIdx] != ' ' {
					hasPrinted = true
					break
				}
			}
			if hasPrinted {
				outInt[i] = ','
			} else {
				outInt[i] = ' '
			}
		}
	}
	fracStr := ""
	if fracLen > 0 {
		fracStr = fmt.Sprintf("%0*d", fracLen, fracPart)
	}
	var result string
	if dotIdx >= 0 {
		result = string(outInt) + "." + fracStr
	} else {
		result = string(outInt)
	}
	if val.IsNegative() {
		// place minus sign at leftmost possible position (simple)
		// not needed for this program (all positive) but handle
		for i := 0; i < len(result); i++ {
			if result[i] != ' ' && result[i] != ',' {
				b := []byte(result)
				// find first space to put minus, else prepend
				placed := false
				for j := i - 1; j >= 0; j-- {
					if b[j] == ' ' {
						b[j] = '-'
						placed = true
						break
					}
				}
				if !placed {
					if b[0] == ' ' {
						b[0] = '-'
					}
				}
				result = string(b)
				break
			}
		}
		if len(result) > 0 && result[0] == ' ' {
			// fallback if all spaces (should not happen)
		}
	}
	return result
}

func openDiscFile() error {
	data, err := os.ReadFile("input.dat")
	if err != nil {
		if os.IsNotExist(err) {
			discLines = nil
			discIdx = 0
			return nil
		}
		return err
	}
	if len(data) == 0 {
		discLines = nil
		discIdx = 0
		return nil
	}
	content := string(data)
	content = strings.ReplaceAll(content, "\r\n", "\n")
	content = strings.ReplaceAll(content, "\r", "\n")
	parts := strings.Split(content, "\n")
	if len(parts) > 0 && parts[len(parts)-1] == "" && len(content) > 0 && content[len(content)-1] == '\n' {
		parts = parts[:len(parts)-1]
	}
	discLines = parts
	discIdx = 0
	return nil
}

func ReadPara() {
	if discIdx >= len(discLines) {
		WsEofFlag = "Y"
		return
	}
	line := discLines[discIdx]
	discIdx++
	if len(line) < 15 {
		line = line + strings.Repeat(" ", 15-len(line))
	} else if len(line) > 15 {
		line = line[:15]
	}
	drItem := line[0:6]
	drPriceRaw := line[6:13]
	drPctRaw := line[13:15]

	// parse price: implied 9(5)V99
	var digits strings.Builder
	for _, c := range drPriceRaw {
		if c >= '0' && c <= '9' {
			digits.WriteRune(c)
		}
	}
	ds := digits.String()
	if ds == "" {
		ds = "0"
	}
	valPrice, _ := decimal.NewFromString(ds)
	valPrice = valPrice.Shift(-2)

	// parse pct: 9(2)
	var digits2 strings.Builder
	for _, c := range drPctRaw {
		if c >= '0' && c <= '9' {
			digits2.WriteRune(c)
		}
	}
	ds2 := digits2.String()
	var pct int64
	if ds2 != "" {
		var n int64
		fmt.Sscan(ds2, &n)
		pct = n % 100
	} else {
		pct = 0
	}

	discRec = DiscRec{
		DrItem:  drItem,
		DrPrice: valPrice,
		DrPct:   pct,
	}
}

func ProcessPara() {
	tmp := discRec.DrPrice.Mul(decimal.NewFromInt(discRec.DrPct)).Shift(-2)
	rounded := tmp.Round(2)
	WsDiscount = storeDecimal(rounded, 5, 2)

	netVal := discRec.DrPrice.Sub(WsDiscount).Truncate(2)
	WsNet = storeDecimal(netVal, 5, 2)

	sum := WsTotalNet.Add(WsNet).Truncate(2)
	WsTotalNet = storeDecimal(sum, 8, 2)

	WsCount = (WsCount + 1) % 1000

	WsPriceEd = formatEdited(discRec.DrPrice, "ZZ,ZZ9.99")
	WsDiscEd = formatEdited(WsDiscount, "ZZ,ZZ9.99")
	WsNetEd = formatEdited(WsNet, "ZZ,ZZ9.99")

	pctStr := fmt.Sprintf("%02d", discRec.DrPct)
	fmt.Printf("%s %s %s%% %s %s\n", discRec.DrItem, WsPriceEd, pctStr, WsDiscEd, WsNetEd)

	ReadPara()
}

func SummaryPara() {
	WsTotalEd = formatEdited(WsTotalNet, "ZZ,ZZZ,ZZ9.99")
	countStr := fmt.Sprintf("%03d", WsCount)
	fmt.Printf("ITEMS: %s NET TOTAL: %s\n", countStr, WsTotalEd)
}

func MainPara() {
	if err := openDiscFile(); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	ReadPara()
	for WsEofFlag != "Y" {
		ProcessPara()
	}
	SummaryPara()
}

func main() {
	MainPara()
}

